-- Only promote untouched non-art drafts. Art records and editor changes are protected.
begin;
create temporary table kk_art_changed(id uuid primary key) on commit drop;
with changed as (
 insert into public.kk_museums as m(id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum)
 select id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum from jsonb_populate_recordset(null::public.kk_museums,'[{"id":"cb87d4f3-78a5-5fb8-b92b-6377ccfa242b","inventory_key":"museum-nl:lalique-museum","name":"Lalique Museum Nederland","city":"Doesburg","province":"Gelderland","street_address":"Gasthuisstraat 1","postal_code":"6981 CP","country":"NL","website_url":"https://www.laliquemuseum.nl/","latitude":52.015227,"longitude":6.134685,"summary":"Ontdek het verfijnde universum van René Lalique. Glas en juwelen tonen zijn gevoel voor natuur, lijn en licht. Tentoonstellingen plaatsen zijn ontwerpen naast tijdgenoten en maken art nouveau en art deco tastbaar.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["glaskunst","sieraden","art nouveau","art deco"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/Doesburg_-_Lalique_Museum_20220615.jpg/1280px-Doesburg_-_Lalique_Museum_20220615.jpg","caption":"Lalique Museum Nederland — Doesburg - Lalique Museum 20220615","credit":"Otter","source_url":"https://commons.wikimedia.org/wiki/File:Doesburg_-_Lalique_Museum_20220615.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"d356e785-836d-50a5-a77e-29baf03bef1d","inventory_key":"museum-nl:museum-rijswijk","name":"Museum Rijswijk","city":"Rijswijk","province":"Zuid-Holland","street_address":"Herenstraat 67","postal_code":"2282 BR","country":"NL","website_url":"https://www.museumrijswijk.nl/","latitude":52.055477,"longitude":4.335343,"summary":"Laat je verrassen door wat papier en textiel kunnen worden. Museum Rijswijk geeft hedendaagse kunstenaars ruimte om materialen te onderzoeken. Tentoonstellingen en biënnales tonen hoe vertrouwde stoffen nieuwe, onverwachte vormen aannemen.","operating_status":"open","publication_status":"draft","verification_status":