m":true},{"id":"a56dbafb-a9a8-5dc6-85e8-0c2198b3f241","inventory_key":"museum-nl:museum-lunteren","name":"Museum Lunteren","city":"Lunteren","province":"Gelderland","street_address":"Dorpsstraat 55","postal_code":"6741 AB","country":"NL","website_url":"https://www.museumlunteren.nl/","latitude":52.083998,"longitude":5.62091,"summary":"Ontdek beeldende kunst in Museum Lunteren en Galerie Goudsberg. Wisselende tentoonstellingen geven professionele kunstenaars een podium naast de lokale geschiedenis. Ontmoet verschillende werkwijzen en neem de tijd voor een nieuwe blik.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","schilderkunst","kunsthal"],"photos":[],"is_art_museum":true},{"id":"76c21b1b-3b3b-5688-bef6-7213e687b89a","inventory_key":"art-audit:300","name":"OSCAM - Open Space Contemporary Art Museum","city":"Amsterdam","province":"Noord-Holland","street_address":"Bijlmerdreef 1289","postal_code":"1103 TV","country":"NL","website_url":"https://www.oscam.nl/about/","latitude":null,"longitude":null,"summary":"Ontdek nieuwe stemmen in kunst, mode en design bij OSCAM. Het museum in Amsterdam-Zuidoost biedt ruimte aan makers en verhalen uit een diverse stad. Wisselende tentoonstellingen nodigen uit tot ontmoeting en herkenning.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","mode","design"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/OSCAM_museum_art_19_maart_2023_%281%29.jpg/1280px-OSCAM_museum_art_19_maart_2023_%281%29.jpg","caption":"OSCAM - Open Space Contemporary Art Museum — OSCAM museum art 19 maart 2023 (1)","credit":"Richardkiwi","source_url":"https://commons.wikimedia.org/wiki/File:OSCAM_museum_art_19_maart_2023_(1).jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"71ca77ee-da1c-51cc-9692-57364ef7e513","inventory_key":"art-audit:301","name":"Stichting Nobilis centrum voor prentkunst","city":"Fochteloo","province":"Friesland","street_address":"Zuideinde 26b","postal_code":"8428 HE","country":"NL","website_url":"https://www.stichtingnobilis.nl/","latitude":null,"longitude":null,"summary":"Ontdek de rijkdom van het gedrukte beeld. Nobilis verzamelt en presenteert prentkunst, met nadruk op figuratief werk uit de tweede helft van de twintigste eeuw. Lijnen, lagen en afdrukken maken ieder blad bijzonder.","operating_status":"temporarily_closed","publication_status":"draft","verification_status":"unreviewed","tags":["prentkunst","grafiek","figuratieve kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/Untitled_Sculpture_by_Hein_Mader%2C_placed_at_Stichting_Nobilis%2C_Fochteloo%2C_Frisia.jpg/1280px-Untitled_Sculpture_by_Hein_Mader%2C_placed_at_Stichting_Nobilis%2C_Fochteloo%2C_Frisia.jpg","caption":"Stichting Nobilis centrum voor prentkunst — Untitled Sculpture by Hein Mader, placed at Stichting Nobilis, Fochteloo, Frisia","credit":"Walkuraxx","source_url":"https://commons.wikimedia.org/wiki/File:Untitled_Sculpture_by_Hein_Mader,_placed_at_Stichting_Nobilis,_Fochteloo,_Frisia.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"bf23d2b3-7171-502b-af61-75c4b4a1364c","inventory_key":"museum-nl:storyworld","name":"Storyworld","city":"Groningen","province":"Groningen","street_address":"Nieuwe Markt 1","postal_code":"9712 KJ","country":"NL","website_url":"https://www.storyworld.nl/","latitude":53.218893,"longitude":6.56983,"summary":"Ontdek hoe getekende werelden tot leven komen. Storyworld verbindt strips, animatie en games en laat je kennismaken met de makers achter de beelden. Verhalen en technieken nodigen uit om zelf anders te kijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["stripkunst","animatie","games","illustratie"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Forum_Groningen_Westseite.jpg/1280px-Forum_Groningen_Westseite.jpg","caption":"Storyworld — Forum Groningen Westseite","credit":"BlankeVla","source_url":"https://commons.wikimedia.org/wiki/File:Forum_Groningen_Westseite.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"729160db-5769-5075-bdd5-96d314fd813a","inventory_key":"art-audit:304","name":"Buitenmuseum","city":"Den Haag","province":"Zuid-Holland","street_address":"Dunne Bierkade 16 A","postal_code":"2512 BC","country":"NL","website_url":"https://buitenmuseum.com/","latitude":null,"longitude":null,"summary":"Ontdek de Haagse plekken waar schilders woonden en werkten. Het Buitenmuseum verbindt historische huizen met verhalen over kunstenaars. Rondleidingen en programma''s brengen de kunstgeschiedenis terug naar de straten waarin zij ontstond.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunstenaarsmuseum","schilderkunst","oude meesters"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/RM17506_Den_Haag_-_Dunne_Bierkade_17.jpg/1280px-RM17506_Den_Haag_-_Dunne_Bierkade_17.jpg","caption":"Buitenmuseum — RM17506 Den Haag - Dunne Bierkade 17","credit":"Michiel1972","source_url":"https://commons.wikimedia.org/wiki/File:RM17506_Den_Haag_-_Dunne_Bierkade_17.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"ba5d88b2-0ac0-5398-aa7f-1a60227a1a14","inventory_key":"art-audit:305","name":"MAS Museum voor Achterhoekse Schilderkunst","city":"Vorden","province":"Gelderland","street_address":"Raadhuisstraat 6","postal_code":"7251 AB","country":"NL","website_url":"","latitude":null,"longitude":null,"summary":"Het Museum voor Achterhoekse Schilderkunst in Vorden is opgeheven. De verzameling is overgedragen aan Stadsmuseum Doetinchem. Deze historische vermelding blijft herkenbaar, zodat de oude locatie niet als bezoekbestemming wordt aangeboden.","operating_status":"closed","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","regionale kunst"],"photos":[],"is_art_museum":true}]'::jsonb)
 on conflict(id) do update set inventory_key=excluded.inventory_key,name=excluded.name,city=excluded.city,province=excluded.province,street_address=excluded.street_address,postal_code=excluded.postal_code,country=excluded.country,website_url=excluded.website_url,latitude=excluded.latitude,longitude=excluded.longitude,summary=excluded.summary,operating_status=excluded.operating_status,publication_status=excluded.publication_status,verification_status=excluded.verification_status,tags=excluded.tags,photos=excluded.photos,is_art_museum=excluded.is_art_museum
 where not m.is_art_museum and m.publication_status='draft'
 and not exists(select 1 from kunstkiezer_private.museum_changes c where c.museum_id=m.id and c.editor_id is not null)
 returning id
) insert into kk_art_changed select id from changed;
